transforms.code:
url = self.view.custom.apiGw + "/api/mlops/status?recipe=" + self.view.custom.recipe
try:
	st = system.util.jsonDecode(system.net.httpGet(url, 3000, 5000))
	return [{'value': c, 'label': c} for c in st['recipe']['classes']]
except Exception, e:
	return [{'value': 'OK', 'label': 'OK'}]

config.script:
user = self.session.props.auth.user.userName or 'ignition'
payload = {'product_recipe': 'ALL', 'reason': 'Ignition Perspective'}
payload['user_name'] = user
payload['user_role'] = self.view.custom.role
try:
	resp = system.net.httpClient(timeout=15000).post(self.view.custom.apiGw + "/api/mlops/retrain", data=payload)
	body = resp.json if resp.good else {}
	self.view.custom.lastMsg = ("OK: " if resp.good else "Error %s: " % resp.statusCode) + (str(body) if resp.good else resp.text)[:240]
except Exception, e:
	self.view.custom.lastMsg = "Sin conexión con la API: %s" % e

